s=page(209,U,'200','ii. Messaging Protocol; Figure 6.8 Web Protocol Stack; iii. Description Protocol; iv. Discovery Protocol','ii۔ میسجنگ پروٹوکول؛ شکل ۶.۸ ویب پروٹوکول اسٹیک؛ iii۔ ڈسکرپشن پروٹوکول؛ iv۔ ڈسکوری پروٹوکول','ii. د پیغام لېږلو پروتوکول؛ انځور ۶.۸ د ویب پروتوکول ټولګه؛ iii. د تشریح پروتوکول؛ iv. د کشف پروتوکول','p200')
F=Flow(s)
def stack():
    b=''
    ls=[('Layer 4','UDDI (Service Discovery)'),('Layer 3','WSDL (Service Description)'),('Layer 2','XML Messaging (XML, SOAP)'),('Layer 1','Transport (HTTP, SMTP, FTP)')]
    for k,(a,t) in enumerate(ls):
        y=10+k*62
        b+=f'<rect x="10" y="{y}" width="240" height="46" fill="#fff" stroke="#111" stroke-width="2"/>'+T(130,y+18,a,12,'middle',700)+T(130,y+36,t,12,'middle',700)
        if k<3: b+=f'<polygon points="130,{y+62} 118,{y+52} 142,{y+52}" fill="#5bc"/>'
    return svg(260,260,'Web protocol stack with four layers from transport to service discovery',b)
s['figures']=[dict(svg=stack(),id='cs11-s209-fig1',caption='Figure 6.8 Web Protocol Stack',captionUrdu='شکل ۶.۸ ویب پروٹوکول اسٹیک',captionPashto='انځور ۶.۸ د ویب پروتوکول ټولګه',labels=[lab('Layer 4 UDDI (Service Discovery)','تہہ ۴ یو ڈی ڈی آئی (سروس ڈسکوری)','طبقه ۴ UDDI (د خدمت کشف)'),lab('Layer 3 WSDL (Service Description)','تہہ ۳ ڈبلیو ایس ڈی ایل (سروس ڈسکرپشن)','طبقه ۳ WSDL (د خدمت تشریح)'),lab('Layer 2 XML Messaging (XML, SOAP)','تہہ ۲ ایکس ایم ایل میسجنگ (ایکس ایم ایل، سوپ)','طبقه ۲ XML پیغام لېږل (XML، SOAP)'),lab('Layer 1 Transport (HTTP, SMTP, FTP)','تہہ ۱ ٹرانسپورٹ (ایچ ٹی ٹی پی، ایس ایم ٹی پی، ایف ٹی پی)','طبقه ۱ لېږد (HTTP، SMTP، FTP)')])]
H(s,'h1','ii. Messaging Protocol','ii۔ میسجنگ پروٹوکول','ii. د پیغام لېږلو پروتوکول')
add(s,'a','It is responsible for encoding messages in a common XML (Extensible Markup Language) format so that they can be understood at either end of a network connection. Currently, this area includes such protocols as XML and SOAP (Simple Object Access Protocol).','یہ پیغامات کو مشترکہ ایکس ایم ایل (ایکسٹینسیبل مارک اپ لینگویج) فارمیٹ میں انکوڈ کرنے کا ذمہ دار ہے تاکہ نیٹ ورک کنکشن کے دونوں سروں پر انہیں سمجھا جا سکے۔ فی الحال اس شعبے میں ایکس ایم ایل اور سوپ (سمپل آبجیکٹ ایکسیس پروٹوکول) جیسے پروٹوکولز شامل ہیں۔','دا د پیغامونو په ګډه XML (پراخېدونکې نښه کولو ژبه) بڼه کې کوډ کولو مسؤل دی ترڅو د شبکې نښلونې په دواړو سرونو کې پوه شي. اوس مهال، دا برخه پروتوکولونه لکه XML او SOAP (ساده څیز لاسرسي پروتوکول) شاملوي.')
F.fg(0)
H(s,'h2','iii. Description Protocol','iii۔ ڈسکرپشن پروٹوکول','iii. د تشریح پروتوکول')
add(s,'b','This protocol is used for describing the public interface to a specific Web service. The WSDL (Web Services Description Language) interface format is typically used for this purpose. WSDL is an XML-based language used to describe the services a business offers and to provide a way for individuals and other businesses to access those services electronically.','یہ پروٹوکول کسی مخصوص ویب سروس کے عوامی انٹرفیس کو بیان کرنے کے لیے استعمال ہوتا ہے۔ اس مقصد کے لیے عموماً ڈبلیو ایس ڈی ایل (ویب سروسز ڈسکرپشن لینگویج) انٹرفیس فارمیٹ استعمال ہوتا ہے۔ ڈبلیو ایس ڈی ایل ایکس ایم ایل پر مبنی زبان ہے جو کسی کاروبار کی پیش کردہ خدمات بیان کرنے اور افراد اور دیگر کاروباروں کو ان خدمات تک برقی طور پر رسائی کا طریقہ فراہم کرنے کے لیے استعمال ہوتی ہے۔','دا پروتوکول د یوې ځانګړې ویب خدمت عامه انټرفیس بیانولو لپاره کارول کېږي. د WSDL (د ویب خدمتونو تشریح ژبه) انټرفیس بڼه معمولاً د دې موخې لپاره کارول کېږي. WSDL یوه XML پر بنسټ ژبه ده چې د یوې سوداګرۍ د وړاندې شویو خدمتونو بیانولو او افرادو او نورو سوداګریو ته د هغو خدمتونو ته په برېښنايي توګه لاسرسي لپاره یوه لار برابرولو لپاره کارول کېږي.')
H(s,'h3','iv. Discovery Protocol','iv۔ ڈسکوری پروٹوکول','iv. د کشف پروتوکول')
add(s,'c','This protocol centralizes services into a common registry. It can publish their location and description, and makes it easy to discover what services are available on the network. Universal Description Discovery and Integration (UDDI) is intended for this purpose. UDDI (Universal Description, Discovery, and Integration) is an XML-based registry for businesses worldwide to list themselves on the Internet. Its ultimate goal is to streamline online transactions by enabling companies to find one another on the Web and make their systems interoperable for e-commerce.','یہ پروٹوکول خدمات کو ایک مشترکہ رجسٹری میں مرکزیت دیتا ہے۔ یہ ان کا مقام اور تفصیل شائع کر سکتا ہے اور نیٹ ورک پر دستیاب خدمات کا پتہ لگانا آسان بناتا ہے۔ یونیورسل ڈسکرپشن ڈسکوری اینڈ انٹیگریشن (یو ڈی ڈی آئی) اسی مقصد کے لیے ہے۔ یو ڈی ڈی آئی (یونیورسل ڈسکرپشن، ڈسکوری اور انٹیگریشن) دنیا بھر کے کاروباروں کے لیے انٹرنیٹ پر خود کو درج کرنے کی ایکس ایم ایل پر مبنی رجسٹری ہے۔ اس کا حتمی مقصد کمپنیوں کو ویب پر ایک دوسرے کو تلاش کرنے اور ای کامرس کے لیے اپنے نظاموں کو باہمی طور پر قابلِ عمل بنانے کے قابل بنا کر آن لائن لین دین کو سہل بنانا ہے۔','دا پروتوکول خدمتونه په یوه ګډ ثبت کې متمرکز کوي. دا کولای شي د هغو موقعیت او تشریح خپره کړي، او په شبکه کې د شته خدمتونو موندل اسانه کوي. د نړیوال تشریح کشف او ادغام (UDDI) د دې موخې لپاره دی. UDDI (نړیوال تشریح، کشف او ادغام) د نړۍ د سوداګریو لپاره په انټرنېټ د ځان لیست کولو لپاره یو XML پر بنسټ ثبت دی. د دې وروستۍ موخه دا ده چې د شرکتونو ته د ویب پر مخ د یو بل موندلو او د برېښنايي سوداګرۍ لپاره د خپلو سیسټمونو د متقابل عملیاتي کولو توان ورکولو سره آنلاین معاملې ګړندۍ کړي.')
F.done()
fin(s,'Printed page 200: “ii. Messaging Protocol” beside Figure 6.8 Web Protocol Stack (four layers: Layer 1 Transport (HTTP, SMTP, FTP), Layer 2 XML Messaging (XML, SOAP), Layer 3 WSDL (Service Description), Layer 4 UDDI (Service Discovery); redrawn as coded SVG), “iii. Description Protocol” and “iv. Discovery Protocol”. The heading “iii.” is printed beside the figure caption.')
